def handle(app, svc):
    resp = svc.apply(app)
    decision = resp.get("decision")
    limit = int(resp.get("limit", 0) or 0)

    # Network rule: self_employed applicant with requested_limit above 6000
    # must go to manual review instead of being issued. A decline stays a decline.
    if (app.get("employment") == "self_employed"
            and int(app.get("requested_limit", 0) or 0) > 6000):
        if decision == "decline":
            return {"action": "decline", "limit": 0}
        return {"action": "queue_review", "limit": 0}

    if decision == "approve":
        return {"action": "issue", "limit": limit}
    if decision == "decline":
        return {"action": "decline", "limit": 0}
    # "refer" (or any other undecided state): manual review queue, do not decline.
    return {"action": "queue_review", "limit": 0}
